window.MONSTER_CHUNK_7 = [{"name":"Kuru","cr":0.5,"xp":200,"race":"kuru","classes":[{"class":"barbarian","level":1}],"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["kuru"],"init":0,"senses":[{"type":"low-light vision"}],"ac":12,"ac_touch":8,"ac_flat_footed":12,"ac_mods":"+4 armor, -2 rage","hp":16,"hd":"1d12+4","hdvalue":1,"fort":5,"ref":2,"will":4,"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":40}],"melee":"club +5 (1d6+6), bite +0 (1d6+2 plus cannibalistic vitality)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"5 rounds/day"}],"strength":19,"dexterity":10,"constitution":16,"intelligence":10,"wisdom":14,"charisma":13,"baseatk":1,"cmb":5,"cmd":13,"feats":[{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Climb","value":5},{"skill":"Intimidate","value":5},{"skill":"Perception","value":6},{"skill":"Survival","value":6}],"sq":[{"type":"fast movement"},{"type":"kuru courage"}],"environments":["any coastal"],"organizations":["pair","gang (3-6)","raid (7-15)","tribe (16+ plus 33% noncombatants, 1 shaman of 3rd level per 20 adults, and 1 leader of 5th-7th level)"],"treasure":"none","description_visual":"Disturbing tribal tattoos cover this red-eyed humanoid's face, and his jagged teeth appear to have been filed down to points.","source":"Isles Of The Shackles","special_abilities":[{"type":"Blood Courage","kind":"Ex","details":"Once per day when a kuru makes a saving throw against a fear effect, he can roll the saving throw twice and take the better result. He must decide to use this ability before the saving throw is attempted."},{"type":"Cannibalistic Vitality","kind":"Ex","details":"When a kuru hits a living creature with its bite attack, he gains 1 temporary hit point by ingesting the target's blood. This ability doesn't work on creatures that don't have blood."}],"description":"Kuru are savage natives of the Shackles, dreadfully transformed by their loathsome \"goddess,\" the Blood Queen. While most kuru live in small tribal villages in or around Ghol-Gan ruins, some choose to abandon their cultic faith and seek adventure beyond the islands from which they hail, though such individuals are extremely rare.","as_character":[{"description":"Kuru are defined by their class levels (they don't possess racial Hit Dice) and have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Dexterity, +2 Constitution, -2 Intelligence: Kuru are abnormally fast and hardy, but bloodlust clouds their thinking."},{"type":"Low-Light Vision","value":"In dim light, kuru can see twice as far as humans."},{"type":"Blood Courage","value":"See above."},{"type":"Cannibalistic Vitality","value":"See above."},{"type":"Light Sensitivity","value":"Natural Weapon: Kuru possess a natural bite attack that deals 1d6 points of damage."},{"type":"Languages","value":"Kuru begin play speaking Kuru. Kuru with high Intelligence scores can choose bonus languages from the following: Abyssal, Common, Polyglot, Undercommon."}]}],"ecology":"","habitat_society":"","gear":"hide armor"},{"name":"Lashunta","cr":0.5,"xp":200,"race":"lashunta","classes":[{"class":"wizard","level":1}],"alignment":"NG","size":"Medium","type":"humanoid","subtypes":["lashunta"],"init":1,"ac":11,"ac_touch":11,"ac_flat_footed":10,"ac_mods":"+1 Dex","hp":8,"hd":"1d6+2","hdvalue":1,"fort":-1,"ref":1,"will":3,"speed":[{"type":"land","speed":30}],"melee":"mwk quarterstaff +0 (1d6-1)","ranged":"light crossbow +1 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hand of the apprentice","details":"6/day"}],"spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":0,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"daze"},{"spell":"mage hand"}]},{"frequency":"1/day","spells":[{"spell":"detect thoughts"}]}],"spellsprepared_caster":"wizard","spellsprepared_caster_level":1,"spellsprepared_concentration":0,"spellsprepared":[{"spell_level":1,"spell_slots":1,"spells":[{"spell":"charm person"},{"spell":"mage armor"},{"spell":"magic missile"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"detect magic"},{"spell":"flare"},{"spell":"read magic"}]}],"strength":8,"dexterity":13,"constitution":8,"intelligence":17,"wisdom":12,"charisma":16,"baseatk":0,"cmb":-1,"cmd":10,"feats":[{"feat":"Scribe Scroll"},{"feat":"Toughness"}],"skills":[{"skill":"Diplomacy","value":4},{"skill":"Handle Animal","value":4},{"skill":"Knowledge (arcana)","value":9},{"skill":"Perception","value":2},{"skill":"Spellcraft","value":7},{"skill":"Use Magic Device","value":4}],"languages":["Celestial","Common","Draconic","Elven","Lashunta","limited telepathy"],"sq":[{"type":"arcane bond","details":"amulet"}],"environments":["any (Castrovel)"],"organizations":["any"],"treasure":"none","description_visual":"Delicate antennae extend from the forehead of this lithe woman.","source":"Inner Sea Bestiary","description":"The lashunta are the primary race of Castrovel, called \"the Green Planet\" for its steaming jungles. Though the women look like idealized elves or humans-save for the twitching antennae sprouting from their foreheads-their men are squat, hairy, and broad-shouldered, with a fierce and confrontational demeanor. Both genders excel at scholarship, and the race boasts a large number of telepaths and telekinetics, in addition to conventional magic-users. This ability to create mental or empathic bonds is particularly prevalent among female warriors, who form close connections with their saurian mounts.\n\nFemale lashunta are typically 6 ft. tall and weigh 140 pounds. The males of the race are usually 5 ft. tall and weigh 200 pounds.","as_character":[{"description":"Lashunta are defined by their class levels-they don't have racial Hit Dice. They have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Intelligence: Lashunta are almost universally intelligent and eager to learn."},{"type":"Sexual Dimorphism","value":"Male and female lashunta have very different body and personality types, more so than most humanoid species. Male lashunta are muscular (+2 Strength) and often brash and unobservant (-2 Wisdom). Female lashunta, though beautiful and commanding (+2 Charisma), lack the males' rugged builds (-2 Constitution)."},{"type":"Lashunta Magic (5 RP)","value":"A lashunta possessing an Intelligence score of 11 or higher gains the following spell-like abilities: At will—daze, mage hand; 1/day-detect thoughts. The caster level for these effects is equal to the lashunta's class levels."},{"type":"Knowledgeable","value":"A lashunta gains a +2 racial bonus to any one Knowledge skill."},{"type":"Limited Telepathy (3 RP)","value":"A lashunta is able to mentally communicate with any creature within 30 ft. with whom she shares a language. Otherwise this ability is identical to the telepathy ability."},{"type":"Languages","value":"Lashunta begin play speaking Lashunta and Elven. Lashunta with high Intelligence scores can choose any languages they want (except Druidic and other secret languages)."}]}],"ecology":"","habitat_society":"","gear":"light crossbow with 20 bolts, quarterstaff, gold amulet [bonded object]"},{"name":"Leaf Leshy","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"plant","subtypes":["leshy","shapechanger"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":13,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+1 armor, +1 Dex, +1 size","hp":5,"hd":"1d8+1","hdvalue":1,"fort":3,"ref":1,"will":1,"immunities":["electricity","sonic","plant traits"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":10},{"type":"fly","speed":10,"maneuverability":"clumsy"}],"speed_mod":"glide","melee":"shortspear +2 (1d4-2/19-20)","ranged":"seedpods +2 touch (1 plus deafen)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":2,"spell_like_abilities_concentration":3,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"pass without trace"}]}],"strength":6,"dexterity":13,"constitution":12,"intelligence":5,"wisdom":12,"charisma":13,"baseatk":0,"cmb":-3,"cmd":8,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":-1},{"skill":"Stealth","value":5,"special":"+9 in forests and jungles"},{"skill":"Survival","value":1,"special":"+5 in forests and jungles"}],"languages":["Druidic","Sylvan","plantspeech (trees)"],"sq":[{"type":"change shape","details":"Small tree; tree shape"},{"type":"verdant burst"}],"environments":["any forests","any hills"],"organizations":["solitary","grove (2-16)"],"treasure":"standard","description_visual":"This little plant person is clad in a winglike leaf cloak and pinecone armor, wielding a twig as a makeshift spear.","group":"Leshy","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Glide","kind":"Ex","details":"A leaf leshy cannot use its fly speed to hover. When flying, a leaf leshy must end its movement at least 5 ft. lower in elevation than it started."},{"type":"Seedpods","kind":"Ex","details":"Leaf leshys sprout explosive acorns, pine cones, or other seedpods, and can hurl these as ranged attacks. A seedpod has a range increment of 10 ft. and detonates on contact to deal 1 point of bludgeoning damage (this damage isn't modified by Strength). Anyone struck by a seedpod must succeed at a DC 11 Fortitude save or be deafened for 1 round. The save DC is Constitution-based."}],"description":"Leaf leshys tend to the well-being of trees, whether natural stands or cultivated orchards. In appearance, they have soft, pulpy-looking bodies and wear clothing made of dozens of leaves. Larger leaves cover their shoulders, often giving them the appearance of wearing cloaks, and most adorn their relatively featureless heads with helmets made from pine cones, nuts, or fruit rinds. This leafy layer of clothing functions as masterwork padded armor for a leaf leshy, but not for any other creature.\n\nLeaf leshys love to play at war. When not laboring on their trees, they wheedle any companions to engage in mock duels with their twig spears, resorting to private weapon drills when they must. In actual battle, they are much more cautious, sticking to cover and harrying their foes with hit-and-run tactics, as they have a strongly developed sense of self-preservation.\n\nGROWING A LEAF LESHY\n\nLeaf leshys are usually grown under the shade of fruit or nut trees. To grow a leaf leshy, the maker plants an acorn and pine cone together, then mounds up leaves, sticks, and needles around them. When first born, a leaf leshy has no armor, leafy cape, or weapon, but can construct them from available materials given a day and left to its own devices (no Craft check required).\n\nLEAF LESHY\n\nCL 5th; Price 1,000 gp\n\nRITUAL\n\nRequirements Knowledge (nature) 5 ranks, magic stone, plant growth, summon nature's ally I; Skill Knowledge (nature) DC 12; Cost 500 gp","ecology":"","habitat_society":""},{"name":"Llama","cr":0.5,"xp":200,"alignment":"N","size":"Medium","type":"animal","init":1,"senses":[{"type":"low-light vision"}],"ac":11,"ac_touch":11,"ac_flat_footed":10,"ac_mods":"+1 Dex","hp":6,"hd":"1d8+2","hdvalue":1,"fort":4,"ref":3,"will":1,"speed":[{"type":"land","speed":40}],"melee":"bite +1 (1d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"spit","details":"+1 ranged touch"}],"strength":12,"dexterity":13,"constitution":15,"intelligence":2,"wisdom":12,"charisma":9,"baseatk":0,"cmb":1,"cmd":12,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"}],"skills":[{"skill":"Acrobatics","value":5,"special":"+9 when jumping"}],"environments":["cold hills","cold mountains","temperate hills","temperate mountains"],"organizations":["solitary","pair","herd (3-15)"],"treasure":"none","description_visual":"This shaggy, hoofed quadruped sports an elongated neck and large, crooked teeth.","source":"Animal Archive","special_abilities":[{"type":"Spit","kind":"Ex","details":"Once per hour, a llama can regurgitate the contents of its stomach, spitting the foul material at a single target within 10 ft. The target must succeed at a DC 12 Fortitude save or be sickened for 1d4 rounds. The save DC is Constitution-based."}],"description":"Perhaps llamas' most distinctive feature is their long necks. Rival males violently bump their necks against one another during fights for dominance among the herd, but overall these social animals are remarkably tame.","ecology":"","habitat_society":""},{"name":"Locathah","cr":0.5,"xp":200,"alignment":"N","size":"Medium","type":"humanoid","subtypes":["aquatic"],"init":1,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 natural","hp":9,"hd":"2d8","hdvalue":2,"fort":3,"ref":1,"will":1,"speed":[{"type":"land","speed":10},{"type":"swim","speed":60}],"melee":"longspear +2 (1d8/x3)","ranged":"light crossbow +2 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","strength":10,"dexterity":12,"constitution":10,"intelligence":13,"wisdom":13,"charisma":11,"baseatk":1,"cmb":1,"cmd":12,"feats":[{"feat":"Weapon Focus (longspear)"}],"skills":[{"skill":"Craft (any one)","value":6},{"skill":"Perception","value":3},{"skill":"Survival","value":6},{"skill":"Swim","value":8}],"languages":["Aquan"],"sq":[{"type":"amphibious"}],"environments":["temperate aquatic","warm aquatic"],"organizations":["solitary","band (2-10)","tribe (11-30 plus 2 fighter sergeants of 1st-3rd level and 1 cleric leader of 3rd-6th level)"],"treasure":"standard (longspear, light crossbow and 10 bolts)","description_visual":"This lean humanoid bears crested fins on its head and back, and has the wide-eyed and wide-lipped face of a fish.","source":"PFRPG Bestiary 2","description":"Simple aquatic creatures shunned by landwalkers and undersea folk alike, locathahs live in tight-knit communities scattered throughout the world's seas, lakes. and waterways.\n\nLocathahs possess scaly ochre skin tinged with green and yellow. Ridged, rust-colored skin covers their chests and stomachs, and a mottled wash of green, brown, and orange colors their fins like aging kelp. Locathahs exude a strong fishy odor when above water that, in addition to their already unnerving appearance, repulses most land dwellers.\n\nDespite this animosity, locathahs go to great lengths to befriend surface folk, offering safe passage through the waters, pointing out dangerous reefs, and hinting at sunken treasures in return for durable ceramics and metal tools and weapons, as well as tubers, which they view as a delicacy.\n\nThese creatures dislike combat and flee when disarmed or outnumbered. Locathahs hold community in the highest regard, never leaving a friend behind and often going to great lengths to retrieve a fallen companion. Among their own kind and races friendly toward them, locathahs are social creatures who live a very human-like, albeit simple, lifestyle. Locathahs work in stone, coral, and bone to produce the crude implements they use. Some take coral work to obsessive levels, with certain clans taking generations to grow their preferred medium in its desired form before carving it. They feed on crustaceans, undersea plants, and shellfish, and rarely on large fish that are caught during ritualized hunts.\n\nLocathah matriarchs serve their undersea tribes not only as chieftains, but also as the primary egg layers of the community. Each adult member of the tribe is responsible for raising a single young locathah as his or her own.\n\nLocathahs tame moray eels, keeping them near their lairs as humans keep dogs. Some locathah soldiers and hunting groups use giant moray eels as mounts, chasing down their quarry and attacking with narrow-tipped spears. More powerful aquatic races use locathahs as slaves, abducting breeding matriarchs to produce a constant wave of new workers.\n\nLocathah stand roughly as tall as humans, yet their fins jut out, giving them an imposing stature. Lean and strong, locathahs weigh roughly 160 pounds.","ecology":"","habitat_society":""},{"name":"Monkey Goblin","cr":0.5,"xp":200,"race":"Monkey goblin","classes":[{"class":"barbarian","level":1}],"alignment":"NE","size":"Small","type":"humanoid","subtypes":["goblinoid"],"init":4,"senses":[{"type":"low-light vision"}],"ac":17,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+2 armor, +4 Dex, +1 size","hp":13,"hd":"1d12+1","hdvalue":1,"fort":3,"ref":4,"will":0,"save_mods":"+2 vs. fear","speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"kukri +4 (1d3+2/18-20)","ranged":"shortbow +6 (1d4/x3) or  net +6 (entangle)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"5 rounds/day"}],"strength":15,"dexterity":18,"constitution":13,"intelligence":10,"wisdom":10,"charisma":6,"baseatk":1,"cmb":2,"cmd":16,"feats":[{"feat":"Exotic Weapon Proficiency (net)"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":14},{"skill":"Perception","value":4},{"skill":"Stealth","value":11},{"skill":"Survival","value":4}],"languages":["Goblin"],"sq":[{"type":"fast movement"},{"type":"prehensile tail"}],"environments":["tropical forests (Mediogalti Island)"],"organizations":["solitary","raiding party (4-9)","warband (10-16)","tribe (17+ plus 100% noncombatants; 1 tribal hunter of 3rd level per 20 adults, 1 or 2 war chiefs of 4th or 5th level, and 1 chieftain of 6th-8th level)"],"treasure":"none","description_visual":"This creature has the wide head and toothy mouth of a goblin with dappled green skin, simian hands and ft., and a long, ratlike tail.","group":"Goblin","source":"Inner Sea Bestiary","special_abilities":[{"type":"Prehensile Tail","kind":"Ex","details":"All monkey goblins have long, flexible tails that they can use to carry objects. They cannot wield weapons with their tails, but the tails do allow them to retrieve small objects stowed on their persons as a swift action."}],"description":"Monkey goblins are an offshoot of the goblin race adapted for life in the high leafy canopies of Golarion's tropical forests. Equipped with ratlike prehensile tails, monkey goblins are as at home in the trees as they are on the ground.\n\nMonkey goblins lead a savage lifestyle, and many take levels in the barbarian class, though warriors and fighters are also common among the race. While spellcasting classes are almost unheard of among them, monkey goblin shamans in the service of demon lords or other dark gods are given a respect by other monkey goblins that borders on fear.","as_character":[{"description":"Monkey goblins are defined by their class levels-they don't have racial Hit Dice. All monkey goblins have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+4 Dexterity, -2 Wisdom, -2 Charisma: Monkey goblins are fast, but foolishly impulsive and disagreeable."},{"type":"Small","value":"Monkey goblins are Small creatures and gain a +1 size bonus to their AC, a +1 size bonus on attack rolls, a -1 penalty to their CMD and on combat maneuver checks, and a +4 size bonus on Stealth checks."},{"type":"Slow Speed","value":"Monkey goblins have a base speed of 20 ft."},{"type":"Low-Light Vision","value":"Monkey goblins can see twice as far as humans in conditions of dim light."},{"type":"Acrobatic","value":"Monkey goblins gain a +2 racial bonus on Acrobatics and Stealth checks."},{"type":"Fearless","value":"Monkey goblins gain a +2 racial bonus on all saving throws against fear."},{"type":"Natural Climber","value":"Monkey goblins have a climb speed of 30 ft."},{"type":"Prehensile Tail","value":"See above."},{"type":"Languages","value":"Monkey goblins begin play speaking Goblin. Monkey goblins with high Intelligence scores can choose from the following: Common, Draconic, Dwarven, Gnoll, Gnome, Halfling, Orc."}]}],"ecology":"","habitat_society":"","gear":"leather armor, kukri, net, shortbow with 10 arrows"},{"name":"Mummified Baboon","cr":0.5,"xp":200,"alignment":"NE","size":"Small","type":"undead","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":13,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 size","hp":6,"hd":"1d8+2","hdvalue":1,"fort":4,"ref":4,"will":1,"dr":"2/-","immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"bite +3 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"servant's curse","details":"DC 12"}],"strength":12,"dexterity":15,"intelligence":2,"wisdom":12,"charisma":14,"baseatk":0,"cmb":0,"cmd":12,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":5}],"environments":["warm ruins"],"organizations":["solitary"],"treasure":"none","description_visual":"Wrapped in strips of cloth, this hairy, stout animal has opposable thumbs, with a pronounced muzzle and bright red buttocks.","source":"AP 81","description":"In Ancient Osirion, baboons were associated with the god Thoth, and were often depicted in art with crescent moons on their heads. Ancient Osirians kept baboons as pets, and old inscriptions show them being led around on leashes or climbing trees to pick dates and figs.","ecology":"","habitat_society":""},{"name":"Nagaji","cr":0.5,"xp":200,"race":"nagaji","classes":[{"class":"fighter","level":1}],"alignment":"LN","size":"Medium","type":"humanoid","subtypes":["reptilian"],"init":2,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 armor, +2 Dex, +1 natural","hp":10,"hd":"1d10","hdvalue":1,"fort":1,"ref":2,"will":1,"save_mods":"+2 vs. mind-affecting effects and poison","speed":[{"type":"land","speed":30}],"melee":"naginataUC +5 (1d8+4/x4) or claw +4 (1d4+4)","ranged":"longbow +3 (1d8/x3)","space":"5 ft.","reach":"5 ft. (10 ft. with naginata)","strength":17,"dexterity":14,"constitution":8,"intelligence":10,"wisdom":13,"charisma":12,"baseatk":1,"cmb":4,"cmd":16,"feats":[{"feat":"Power Attack"},{"feat":"Weapon Focus (naginata)"}],"skills":[{"skill":"Handle Animal","value":3},{"skill":"Perception","value":4},{"skill":"Survival","value":5}],"languages":["Common","Draconic"],"environments":["warm forests","warm hills"],"organizations":["solitary","war band (2-12)","clan (12-24)"],"treasure":"none","description_visual":"This dark-scaled reptilian humanoid has lidless eyes, and a serpentine tongue that flickers from a fanged, lipless mouth.","source":"PFRPG Bestiary 4","description":"The nagaji are a race of ophidian humanoids created by true nagas to serve as slaves. Vaguely humanlike in appearance, with scaled skin that mimics the colors and patterns of various true nagas, nagaji have forked tongues and lidless eyes, giving them an unblinking gaze that most other races find unnerving. Nagaji venerate nagas as their creators, even going so far as to deify them. Despite the inf luence of their creators, nagaji maintain their own distinct cultures containing elements borrowed from those of both nagas and humans. They prefer warm to tropical regions and settle in wild, isolated regions such as steaming jungles, vast swamps, or volcanic mountains where they erect large temples in honor of their naga creators. These magnificent temples are surrounded by dozens of simple mud daub huts and clay brick structures, which serve as the nagaji's homes and public buildings. Nagaji typically stand between 5-1/2 and 6 ft. tall and weigh about 175 pounds.","as_character":[{"description":"Nagaji are defined by class levels-they don't possess racial Hit Dice. Nagaji have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Strength, +2 Charisma, -2 Intelligence: Nagaji have strong bodies and personalities, but disdain intellectualism."},{"type":"Medium","value":"Nagaji are Medium creatures and have no bonuses or penalties due to their size."},{"type":"Normal Speed","value":"Nagaji have a base speed of 30 ft."},{"type":"Low-Light Vision","value":"Nagaji can see twice as far as humans in conditions of dim light."},{"type":"Armored Scales","value":"Nagaji have a +1 natural armor bonus due to their scaly flesh."},{"type":"Resistant (Ex)","value":"Nagaji receive a +2 racial saving throw bonus against mind-affecting effects and poison."},{"type":"Serpent's Sense (Ex)","value":"Nagaji receive a +2 racial bonus on Handle Animal checks against reptiles, and a +2 racial bonus on Perception checks."},{"type":"Languages","value":"Nagaji begin play speaking Common and Draconic. Nagaji with high Intelligence scores can choose from the following: any human language, Abyssal, Aklo, Celestial, Draconic, Giant, Infernal, and Sylvan."}]}],"ecology":"","habitat_society":"","gear":"leather armor, longbow with 20 arrows, naginata"},{"name":"Oread","cr":0.5,"xp":200,"race":"Oread","classes":[{"class":"fighter","level":1}],"alignment":"N","size":"Medium","type":"outsider","subtypes":["native"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 armor, +2 Dex","hp":12,"hd":"1d10+2","hdvalue":1,"fort":4,"ref":2,"will":4,"resists":[{"type":"acid","value":5}],"speed":[{"type":"land","speed":20}],"melee":"longsword +3 (1d8+3/19-20)","ranged":"composite longbow +4 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":3,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"magic stone"}]}],"strength":15,"dexterity":15,"constitution":14,"intelligence":8,"wisdom":14,"charisma":8,"baseatk":1,"cmb":3,"cmd":15,"feats":[{"feat":"Iron Will"},{"feat":"Weapon Focus (longbow)"}],"skills":[{"skill":"Intimidate","value":4}],"languages":["Common","Terran"],"sq":[{"type":"elemental affinity"}],"environments":["any land"],"organizations":["solitary","pair","team (3-5)"],"treasure":"NPC Gear (leather armor, longsword, composite longbow with 20 arrows)","description_visual":"This large warrior appears heavy and solid, with chiseled, angular features that make her look almost like a statue brought to life.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Earth Affinity","kind":"Ex","details":"Oread sorcerers with the Elemental (earth) bloodline treat their Charisma score as 2 points higher for all sorcerer spells and class abilities. Oread clerics with the Earth domain cast their domain powers and spells at +1 caster level."}],"description":"Oreads are humans whose ancestry includes the touch of an elemental being of earth somewhere along its line, often that of a shaitan genie. Oreads are strong and solidly built, and prefer wearing earth tones that match the coloration of their flesh and hair-shades of gray, brown, black, or white. In rare cases, oreads' stone-like traits are so strong as to leave no question as to their nature, with growths like rocky outcroppings protruding from their skin or hair like crystalline spikes.\n\nOreads tend to be stoic and contemplative, slow to anger but terrible when roused. Outside of combat, they tend to be quiet, dependable, and protective of their friends.","as_character":[{"description":"Oreads are defined by class levels-they don't possess racial Hit Dice. Oreads have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Strength, +2 Wisdom, -2 Charisma: Oreads are strong, solid, stable, and stoic."},{"type":"Darkvision","value":"Oreads can see in the dark up to 60 ft."},{"type":"Spell-Like Ability","value":"Magic stone 1/day (caster level equals the oread's total Hit Dice)."},{"type":"Energy Resistance","value":"Oreads have acid resistance 5."},{"type":"Earth Affinity","value":"See above."},{"type":"Languages","value":"Oreads begin play speaking Common and Terran. Oreads with high Intelligence scores can choose any of the following bonus languages: Aquan, Auran, Dwarven, Elven, Gnome, Halfling, Ignan, and Undercommon."}]}],"ecology":"","habitat_society":""},{"name":"Phlegmatic Ooze Swarm","cr":0.5,"xp":200,"alignment":"N","size":"Tiny","type":"ooze","subtypes":["swarm"],"init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":7,"ac_touch":7,"ac_flat_footed":7,"ac_mods":"-5 Dex, +2 size","hp":8,"hd":"1d8+4","hdvalue":1,"fort":4,"ref":-5,"will":-5,"immunities":["ooze traits","swarm traits"],"resists":[{"type":"cold","value":5}],"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":10}],"melee":"swarm (1 plus viscous)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 14"},{"type":"maddening slime"},{"type":"viscous","details":"DC 14"}],"strength":10,"dexterity":1,"constitution":18,"wisdom":1,"charisma":1,"baseatk":0,"cmb":-7,"cmd":4,"cmd_special":"can't be tripped","environments":["any underground"],"organizations":["solitary","pair","sputum (3-6)","jelly (3-5 phlegmatic ooze swarms and 1-3 sanguine ooze swarms)"],"treasure":"none","description_visual":"Dozens of tiny globs of slime move on their own, acting as one being, alternately clinging to each other and separating in a riot of oozing momentum.","group":"Ooze","source":"AP 43","special_abilities":[{"type":"Maddening Slime","kind":"Ex","details":"Phlegmatic oozes are composed of volatile, mind-altering secretions. Any living creature that begins its turn affected by the phlegmatic ooze's viscous ability must make a DC 14 Fortitude save or be confused for 1 round. This is a mind-affecting effect. Creatures immune to poison are immune to this effect."},{"type":"Viscous","kind":"Ex","details":"As described in the sanguine ooze swarm's special abilities, except the Reflex save DC is 14 and the patches are destroyed if the victim takes any amount of fire damage."}],"description":"Formed from accumulations of runoff from arcane laboratories and regions of magical calamity, alchemical oozes are fist-sized blobs of volatile chemicals. Although composed of unpredictable compounds and toxins, these mobile oozes pose little threat individually, but in polluted quagmires and tainted sewers can collect in numbers great enough to threaten creatures many times their size. Swarms of the slimes linger in such contaminated areas and seek new accretions of vital solutions, like those found within the bodies of higher life forms, to fuel their erratic life cycles. Found in numerous varieties with a host of differing abilities, these weird, clinging oozes have been differentiated by likening them to the humors said to compose the bodies of living beings. Appearing at first to be a collection of tiny blobs of viscous, translucent fluid, alchemical oozes become far more terrifying once their hungry nature becomes apparent. Each swarm is composed of several hundred palm-sized balls of ooze that all scuttle along as a single unit.","ecology":"","habitat_society":""},{"name":"Plague Zombie","cr":0.5,"xp":200,"alignment":"NE","size":"Medium","type":"undead","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":12,"ac_touch":10,"ac_flat_footed":12,"ac_mods":"+2 natural","hp":12,"hd":"2d8+3","hdvalue":2,"fort":0,"ref":0,"will":3,"immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"slam +4 (1d6+4 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death burst"}],"strength":17,"dexterity":10,"wisdom":10,"charisma":10,"baseatk":1,"cmb":4,"cmd":14,"feats":[{"feat":"Toughness","type":"bonus"}],"sq":[{"type":"staggered"}],"environments":["any"],"organizations":["any"],"treasure":"none","description_visual":"This walking corpse wears only a few soiled rags, its flesh rotting off its bones as it stumbles forward, arms outstretched.","group":"Zombie","source":"PFRPG Bestiary","special_abilities":[{"type":"Death Burst","kind":"Ex","details":"When a plague zombie dies, it explodes in a burst of decay. All creatures adjacent to the plague zombie are exposed to its plague as if struck by a slam attack and must make a Fortitude save or contract zombie rot."},{"type":"Disease","kind":"Su","details":"The slam attack - as well as any other natural attacks - of a plague zombie carries the zombie rot disease. Zombie rot: slam; save Fort DC 11; onset 1d4 days; frequency 1/day; effect 1d2 Con, this damage cannot be healed while the creature is infected; cure 2 consecutive saves. Anyone who dies while infected rises as a plague zombie in 2d6 hours."},{"type":"Staggered","kind":"Ex","details":"Zombies have poor reflexes and can only perform a single move action or standard action each round. A zombie can move up to its speed and attack in the same round as a charge action."}],"description":"These zombies carry a terrible disease that perpetuates their undead lineage-those infected by a plague zombie's contagion rise as zombies themselves when they perish.","ecology":"","habitat_society":""},{"name":"Poison Frog","cr":0.5,"xp":200,"alignment":"N","size":"Tiny","type":"animal","init":1,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":3,"will":-1,"speed":[{"type":"land","speed":10},{"type":"swim","speed":20}],"melee":"bite +3 (1 plus poison)","space":"2-1/2 ft.","reach":"0 ft.","strength":2,"dexterity":12,"constitution":11,"intelligence":1,"wisdom":9,"charisma":10,"baseatk":0,"cmb":-1,"cmd":5,"cmd_special":"+4 vs. trip","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":5,"special":"+1 jumping"},{"skill":"Perception","value":3},{"skill":"Stealth","value":13},{"skill":"Swim","value":9}],"environments":["warm aquatic","warm marshes"],"organizations":["solitary","pair","army (3-12)"],"treasure":"none","description_visual":"This small frog is bright green and red, with electric-blue stripes on its hind legs.","group":"Frog","source":"PFRPG Bestiary","special_abilities":[{"type":"Poison","kind":"Ex","details":"Injury; save Fort DC 10; frequency 1/round for 6 rounds; effect 1d2 Con damage; cure 1 save"}],"description":"Poisonous frogs are a bright green color, with additional bright yellow, red, or blue markings. They are just over a foot long and weigh 10 pounds. The poison of poisonous frogs is often gathered by primitive tribes and used to coat darts and arrows for hunting. You can make a larger poison frog either by applying the giant simple template or by giving a normal giant frog a poison frog's venomous bite.","ecology":"","habitat_society":""},{"name":"Pony","cr":0.5,"xp":200,"alignment":"N","size":"Medium","type":"animal","init":1,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":11,"ac_touch":11,"ac_flat_footed":10,"ac_mods":"+1 Dex","hp":13,"hd":"2d8+4","hdvalue":2,"fort":5,"ref":4,"will":0,"speed":[{"type":"land","speed":40}],"melee":"2 hooves -3 (1d3)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":13,"constitution":14,"intelligence":2,"wisdom":11,"charisma":4,"baseatk":1,"cmb":2,"cmd":13,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Run","type":"bonus"}],"skills":[{"skill":"Perception","value":5}],"sq":[{"type":"docile","details":"see horse"}],"environments":["temperate plains"],"organizations":["solitary","pair","herd (3-30)"],"treasure":"none","description_visual":"This squat equine plods forward with large, curious eyes. As it nears, it extends its muzzle, clearly expecting a treat.","group":"Horse","source":"PFRPG Bestiary","description":"Ponies are smaller breeds of horses better suited to half lings, gnomes, and dwarves, but they also make fond pets for humans as well. They stand 3 to 4 ft. tall and weigh about 600 pounds. A light load for a pony is up to 100 pounds, a medium load is 101-200 pounds, and a heavy load is 201-300 pounds. A pony can drag 1,500 pounds. The statistics presented above are for a typical pony. Tougher ponies with the advanced simple template exist, but are relatively uncommon and, unlike horses, these creatures are not generally called \"heavy ponies.\" Like horses, ponies can be trained for combat with the Handle Animal skill, and such mounts often serve half lings, gnomes, and other small races as steeds in combat.","ecology":"","habitat_society":""},{"name":"Pugwampi","cr":0.5,"xp":200,"alignment":"NE","size":"Tiny","type":"fey","init":5,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"}],"auras":["unluck (20 ft.)"],"ac":13,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 size","hp":6,"hd":"1d6+3","hdvalue":1,"fort":0,"ref":3,"will":4,"dr":"2/cold iron","sr":7,"speed":[{"type":"land","speed":30}],"melee":"dagger +3 (1d2-4/19-20)","ranged":"shortbow +3 (1d3-4/x3)","space":"2-1/2 ft.","reach":"0 ft.","spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":1,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"prestidigitation"},{"spell":"speak with animals"}]},{"frequency":"1/day","spells":[{"spell":"shatter"}]}],"strength":3,"dexterity":13,"constitution":11,"intelligence":10,"wisdom":14,"charisma":6,"baseatk":0,"cmb":-1,"cmd":5,"feats":[{"feat":"Improved Initiative"},{"feat":"Toughness","type":"bonus"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Bluff","value":2},{"skill":"Craft (traps)","value":4},{"skill":"Disable Device","value":2},{"skill":"Perception","value":6,"special":"+2 Listening"},{"skill":"Ride","value":2},{"skill":"Stealth","value":17}],"languages":["Gnoll","Undercommon"],"environments":["warm hills"],"organizations":["solitary","pair","mob (3-12)","infestation (13-20 with 1-3 druids of 1st-3rd level, 1 fighter leader of 2nd-4th level, 2-8 trained stirges, and 2-5 trained baboons)"],"treasure":"standard (dagger, shortbow with 20 arrows)","description_visual":"As if the world's most revolting lapdog had somehow learned to walk on its back legs, this sickly creature slinks forward carefully.","group":"Gremlin","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Unluck Aura","kind":"Su","details":"A pugwampi radiates an aura of unluck to a radius of 20 ft. Any creature in this area must roll two d20s whenever a situation calls for a d20 roll (such as an attack roll, a skill check, or a saving throw) and must use the lower of the two results generated. This is a mind-affecting effect that doesn't work on animals, other gremlins, or gnolls. Any character who gains any sort of luck bonus (such as that granted by a luckstone or divine favor) is immune to the pugwampi unluck aura."}],"description":"Mean, dog-faced, and cowardly, pugwampis are loved by no one-not even other gremlins. These gremlins take disproportionate amounts of enjoyment from the accidents and missteps of other creatures, often going to great lengths to manufacture the perfect deadfalls or stumbling blocks. They then wait nearby, both to laugh at the inevitable mishaps and to make sure their personal unluckiness is passed off on their victims.\n\nPugwampis live in caves or ruined buildings, occasionally venturing forth to find victims upon which to inf lict their sick senses of humor. Their \"jokes\" tend to involve spikes and excrement, or sometimes pits full of spiders or campsites that flood with swamp water.\n\nCertainly only the pugwampis consider their jokes funny.\n\nAs all pugwampis are somewhat deaf, when not trying to be stealthy, they tend to scream and yell loudly so they can hear themselves and each other.\n\nAt some point in the distant past, pugwampis became enamored of gnolls, seeing in the beast-men a kindred form and thus aspiring to the height and deadly prowess of the savage warriors, whom they honor as gods. Gnolls, for their part, hate pugwampis even more than other creatures, mostly because of the gremlins' weakness and sickening fawning, though they sometimes keep the gremlins around just to torment them.","ecology":"","habitat_society":""},{"name":"Raccoon","cr":0.5,"xp":200,"alignment":"N","size":"Tiny","type":"animal","init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 natural, +2 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":4,"will":3,"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"bite +4 (1d3-1)","space":"2-1/2 ft.","reach":"0 ft.","strength":8,"dexterity":15,"constitution":11,"intelligence":2,"wisdom":16,"charisma":5,"baseatk":0,"cmb":0,"cmd":9,"cmd_special":"+4 vs. trip","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":10},{"skill":"Sleight of Hand","value":3}],"environments":["temperate forests"],"organizations":["solitary","gaze (2-4)"],"treasure":"none","description_visual":"Presented on these pages are base animal statistics for six additional familiars beyond those most commonly used by spellcasters-of course, these statistics can also be used for normal animals as well. These familiars utilize all the standard rules for familiars. Tiny or smaller familiars in this section use Dexterity to modify Climb and Swim skill checks.","group":"Familiar","source":"PFRPG Bestiary 3","description":"Raccoons are inquisitive and cunning, and often have strangely humanoid mannerisms, like washing their food in streams.","ecology":"","habitat_society":""},{"name":"Sagari","cr":0.5,"xp":200,"alignment":"NE","size":"Tiny","type":"aberration","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 size","hp":7,"hd":"1d8+3","hdvalue":1,"fort":3,"ref":4,"will":2,"speed":[{"type":"land","speed":10},{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"bite +1 (1d4-1), tentacle +1 (1d4-1)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"baleful whinny"},{"type":"lashing strike"}],"strength":8,"dexterity":15,"constitution":17,"intelligence":6,"wisdom":11,"charisma":14,"baseatk":0,"cmb":0,"cmd":9,"cmd_special":"can't be tripped","feats":[{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Fly","value":14},{"skill":"Perception","value":4},{"skill":"Stealth","value":14}],"languages":["Aklo"],"sq":[{"type":"flight"}],"environments":["any forests"],"organizations":["solitary","pair","herd (3-8)","harras (9-16)"],"treasure":"none","description_visual":"This unsettling creature has the head of a fanged, green-eyed horse and a body that is little more than a writhing tentacle.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Baleful Whinny","kind":"Su","details":"As a standard action, a sagari can emit a monstrous whinny. Any creature within 60 ft. must succeed at a DC 12 Will save or become sickened for 1d4 rounds by the hideous sound. This is a sonic, mind-affecting effect. Whether or not the save is successful, the affected creature is immune to the same sagari's baleful whinny for 24 hours. The save DC is Charisma-based."},{"type":"Flight","kind":"Su","details":"A sagari's flight is supernatural in nature."},{"type":"Lashing Strike","kind":"Ex","details":"Although a sagari is Tiny, it doesn't provoke attacks of opportunity when it makes melee attacks. In addition, its tentacle attack is a primary attack."}],"description":"Sagaris haunt forest trails, hanging upside-down from tree branches by the grotesque tentacles that make up their necks. Unexpectedly intelligent, these cruel aberrations swoop down from their perches to attack unsuspecting travelers wandering through the forests. Their piercing whinny causes sickness within those who hear it, the sound waves reverberating within the victims' chests and causing them to feel unwell. Groups of sagaris are particularly dangerous, filling the air with\n\ntheir terrifying neighs and diving upon utterly helpless, nauseated victims in a rush.\n\nThe tentacle of a sagari isn't strong enough to grab or strangle enemies, but serves the creature well as an additional attack to augment its bite. Sagaris are strictly carnivorous, and while they resort to feeding on carrion if necessary, they greatly prefer fresh meat. When a sagari makes its way into a settlement either to wreak havoc or by accident, it can be found hanging from the rafters of a barn or some other structure with a tall ceiling. Stabled livestock are ideal prey for sagaris, who can swiftly kill and devour the flesh of a trapped animal in minutes. A sagari will not attack a creature that it suspects is much stronger, though it will sometimes assault groups of creatures, hoping to sicken enough of its foes to distract them while it attacks the weakest individual.\n\nSagaris are thought to have originally come from the vast caverns beneath the world's surface. While sagaris can speak, they rarely do so with those they deem prey, seeing little point in communicating with food. Despite their relative intelligence, sagaris rarely form societies of any nature, at most traveling in roving packs in search of larger prey to take down as a group.\n\nA sagari is 3 ft. long from mouth to tentacle and weighs 30 pounds.","ecology":"","habitat_society":""},{"name":"Sailors","cr":0.5,"xp":200,"race":"Human","classes":[{"class":"rogue","level":1}],"alignment":"CN","size":"Medium","type":"humanoid","subtypes":["human"],"init":3,"ac":16,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 armor, +3 Dex, +1 dodge","hp":9,"hd":"1d8+1","hdvalue":1,"fort":1,"ref":5,"will":0,"speed":[{"type":"land","speed":30}],"melee":"falchion +2 (2d4+3/18-20) or   mwk dagger +3 (1d4+3/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":15,"dexterity":16,"constitution":13,"intelligence":12,"wisdom":10,"charisma":8,"baseatk":0,"cmb":2,"cmd":16,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Bluff","value":3},{"skill":"Climb","value":6},{"skill":"Diplomacy","value":3},{"skill":"Disable Device","value":7},{"skill":"Escape Artist","value":7},{"skill":"Intimidate","value":3},{"skill":"Knowledge (local)","value":5},{"skill":"Perception","value":4},{"skill":"Sense Motive","value":4},{"skill":"Swim","value":6}],"languages":["Common","Polyglot"],"sq":[{"type":"trapfinding","details":"+1"}],"environments":["any coastlines","any oceans"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This rugged character is clad in colorful, mismatched clothing, his hair tied back in a bandana.","group":"Pirate","source":"Isles Of The Shackles","description":"The average pirate is a free-spirited renegade who would have great difficulty surviving in the cultured depths of polite, civilized society. Rogues and fighters typically make up the majority of a pirate ship's crew of sailors, as they possess both the skill and brawn necessary for day-to-day raids and heists. These colorful, adventurous characters chafe at society's laws and restrictions, and the exciting life of the buccaneer is well suited to pirates' ferocious independence.","ecology":"","habitat_society":"","gear":"leather armor, falchion, masterwork dagger"},{"name":"Samsaran","cr":0.5,"xp":200,"race":"samsaran","classes":[{"class":"oracle","level":1}],"alignment":"N","size":"Medium","type":"humanoid","subtypes":["samsaran"],"init":2,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+3 armor, +2 Dex","hp":11,"hd":"1d8+3","hdvalue":1,"fort":0,"ref":2,"will":4,"save_mods":"+2 vs. death effects, negative energy effects, negative levels","speed":[{"type":"land","speed":30}],"melee":"spear -1 (1d6-1)","ranged":"sling +2 (1d4-1)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":1,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"comprehend languages"},{"spell":"deathwatch"},{"spell":"stabilize"}]}],"spellsknown_caster":"oracle","spellsknown_caster_level":1,"spellsknown_concentration":1,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"command"},{"spell":"cure light wounds"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"ghost sound"},{"spell":"guidance"},{"spell":"light"},{"spell":"mage hand"},{"spell":"read magic"},{"spell":"resistance"}]}],"strength":8,"dexterity":14,"constitution":11,"intelligence":12,"wisdom":14,"charisma":15,"baseatk":0,"cmb":-1,"cmd":11,"feats":[{"feat":"Toughness"}],"skills":[{"skill":"Diplomacy","value":6},{"skill":"Disable Device","value":7},{"skill":"Heal","value":6},{"skill":"Knowledge (religion)","value":5},{"skill":"Perception","value":8},{"skill":"Spellcraft","value":5}],"languages":["Celestial","Common","Draconic","Samsaran"],"sq":[{"type":"lifebound"},{"type":"oracle's curse","details":"haunted"},{"type":"revelations","details":"think on it"},{"type":"shards of the past","details":"Disable Device, Perception"}],"environments":["any land"],"organizations":["solitary","clan (3-12)"],"treasure":"none","description_visual":"This serene-looking slender young man has pale blue skin and solid black eyes, and is dressed in simple robes.","source":"PFRPG Bestiary 4","description":"Samsarans are a race of humanoids whose spirits naturally reincarnate into another samsaran upon death. They have dark hair, pale bluish skin, and eyes with no visible pupil or iris. A samsaran's blood is clear like water. Each samsaran is born with the knowledge that it has lived before, and shall continue onward after death through the cycle of reincarnation. When a samsaran dies, its body fades from sight, and another samsaran child appears somewhere and matures at the normal rate. Samsarans can reproduce with humans and produce true human offspring. Typical samsarans pursue simple, ascetic lives apart from mainstream society. They live in small isolated farming communities as individuals or couples, with older samsarans adopting newly manifested children. Some work as consultants, mediators, prophets, or seers.","as_character":[{"description":"Samsarans are defined by class levels-they don't have racial Hit Dice. Samsarans have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Intelligence, +2 Wisdom, -2 Constitution: Samsarans are insightful and strong-minded, but their bodies tend to be frail."},{"type":"Medium","value":"Samsarans are Medium creatures and have no bonuses or penalties due to their size."},{"type":"Normal Speed","value":"Samsarans have a base speed of 30 ft."},{"type":"Low-Light Vision (Ex)","value":"Samsarans can see twice as far as humans in conditions of dim light."},{"type":"Lifebound (Ex)","value":"Samsarans gain a +2 racial bonus on saving throws against death effects, negative energy effects, saves to remove negative levels, and Con checks to stabilize."},{"type":"Spell-Like Abilities (Sp)","value":"Samsarans with a Charisma score of 11 or higher gain the following: 1/day-comprehend languages, deathwatch, stabilize. The caster level is equal to the samsaran's character level."},{"type":"Shards of the Past (Ex)","value":"A samsaran gains a +2 bonus on any two skills and these become class skills."},{"type":"Languages","value":"Samsarans begin play speaking Common and Samsaran. Those with high Intelligence scores can choose from the following: any human language, Abyssal, Aquan, Auran, Celestial, Draconic, Giant, Ignan, Infernal, and Terran."}]}],"ecology":"","habitat_society":"","gear":"studded leather, spear, sling with 10 bullets, thieves' tools"},{"name":"Shabti","cr":0.5,"xp":200,"race":"Shabti","classes":[{"class":"oracle","level":1}],"alignment":"LN","size":"Medium","type":"outsider","subtypes":["native"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":11,"ac_touch":11,"ac_flat_footed":10,"ac_mods":"+1 Dex","hp":12,"hd":"1d8+4","hdvalue":1,"fort":3,"ref":1,"will":1,"defensive_abilities":["immune to undeath","resist level drain"],"speed":[{"type":"land","speed":30}],"melee":"club +0 (1d6)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"suggestion"}]}],"spellsknown_caster":"oracle","spellsknown_caster_level":1,"spellsknown_concentration":8,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"command"},{"spell":"cure light wounds"},{"spell":"summon monster I"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"create water"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"stabilize"}]}],"strength":10,"dexterity":12,"constitution":16,"intelligence":13,"wisdom":8,"charisma":17,"baseatk":0,"cmb":0,"cmd":11,"feats":[{"feat":"Combat Casting"}],"skills":[{"skill":"Diplomacy","value":7},{"skill":"Knowledge (religion)","value":5},{"skill":"Perception","value":3},{"skill":"Sense Motive","value":3},{"skill":"Spellcraft","value":5}],"languages":["Celestial","Common"],"sq":[{"type":"immortal"},{"type":"oracle's curse","details":"haunted"},{"type":"past-life knowledge"},{"type":"revelations","details":"coat of many stars"},{"type":"shattered soul"}],"environments":["any"],"organizations":["solitary","retinue (1 shabti with 2d4 human commoners)"],"treasure":"none","description_visual":"Light shimmers across this humanoid figure's bare golden skin, illuminating regal features.","source":"AP 84","special_abilities":[{"type":"Immortal","kind":"Ex","details":"Shabti don't age naturally and cannot die of old age. While some might come into being at age categories other than adulthood, they never leave their original age category. Spells and effects that cause aging affect a shabti as normal."},{"type":"Immune to Undeath","kind":"Ex","details":"Shabti can't become undead. Spells and abilities that would transform a shabti into an undead creature have no effect."},{"type":"Past-Life Knowledge","kind":"Ex","details":"Shabti remember bits of their past lives. As a result, they treat all Knowledge skills as class skills."},{"type":"Resist Level Drain","kind":"Ex","details":"A shabti takes no penalties from energy drain effects, though he can still be killed if he accrues more negative levels than he has Hit Dice. After 24 hours, any negative levels a shabti takes are automatically removed without the need for an additional saving throw."},{"type":"Shattered Soul","kind":"Ex","details":"Shabti who are killed are exceptionally difficult to return to life. Those who attempt to return a shabti to life using raise dead, resurrection, or similar spells must succeed at a caster level check equal to 10 + the shabti's Hit Dice. If this check fails, the spell fails and the caster can't return the shabti to life for the next 24 hours (though the caster can try again after this period)."}],"description":"Death is more terrifying for those who have the best of life. Many rulers obsess over their mortality, the most brazen turning to the mystical arts, pouring their fears into splendid vessels, fashioning simulacra of themselves to bear the scourge of Pharasma's judgment. In the mortal world, these icons are nothing but gold with a ruler's face and name, but in death, they are shabti.\n\nExisting as something between mortal souls, fabricated beings, and true children of the planes, shabti are immortal facsimiles of death-obsessed nobles. They serve out the sentences of their mortal twins, whether it be an infinity of torture or an eternity wandering the planes. Most never emerge from such trials, but some manage to find their own paths upon the planes.\n\nShabti typically look like idealized humans with perfect physiques and flawless features. They usually stand just over 6 ft. tall and weigh between 150 and 210 pounds.\n\nEcology\n\nShabti are artificially created creatures, brought into being by mortal magic interfering with the natural course of souls. They are born when an individual of royal blood makes use of a rare magical item known as a sovereign shabti. The methods of creating these soul-guarding relics number among the deepest secrets of royal dynasties and cultic societies, meaning few mortals have access to such magic. However, groups on countless disparate worlds have discovered various routes to this power. This proliferation, along with the race's immortality, means that while shabti are rare sights in most planar metropolises, they are certainly not total strangers. They're practically unknown on the Material Plane, and are typically mistaken for aasimars or ifrits. Still, traditions and superstitions harkening back to this magic make the placement of mundane versions of these figurines-called ushabti-common in Osirian tombs\n\nShabti appear when a paranoid noble uses a sovereign shabti in an effort to avoid their judgment. They come into being full-grown and possessing glimpses from a life of privilege, yet knowing nothing of the magic that spawned them or the karmic debts they've been burdened with. Some appear on the terrifying thresholds of evil-aligned planes among legions of doomed petitioners. Others might simply wander onto the planes from the mists of the Maelstrom.\n\nMost shabti have golden skin that feels cool but not metallic, which is regularly accented by gemstone veins, nails, or other embellishments. Some have skin tones more similar to jade, ivory, or ebony. Apart from their distinctive colorations, shabti have anatomies similar to humans. However, all shabti are sterile, preventing the race from propagating naturally. As such, childlike shabti are exceedingly rare.\n\nHabitat & Society\n\nMost shabti can be found in the planar metropolis of Axis, though Dis, Heaven's Shore, and the City of Brass also seem to be to many shabti's liking. Even in such places, though, shabti rarely gather in groups larger than two or three. Many seek to distinguish themselves from the magic items that spawned them, adopting self-chosen family names- \"Answerers\" and \"Crowns\" being popular among some.\n\nUpon their creation, shabti don't realize they're copies of another being. Each individual initially believes he is a deceased member of royalty, usually taking his rich appearance as a sign of divine favor or spiritual value. Most prove quite indignant, then distraught, in the face of their torture or forced labor. Eventually, they discover their unusual nature. Many deny the notion, choosing to live as if their copied memories were their own. Others face ages of depression, madness, and self-destruction. Some, however, embrace the freedom of a new, rare existence and seek to live up to the splendid forms fate has granted them.\n\nMany shabti learn of their nature from psychopomps. As Pharasma naturally despises such attempts to circumvent the natural cycle, her psychopomps are constantly on the lookout for shabti. When they find shabti, they immediately free them from any punishments, then use the shabti's memories to track down their mortal creators and bring them to justice.","as_character":[{"description":"Liberated shabti often explore the planes, seeking to replace their false memories with unique experiences. Shabti are defined by their class levels-they don't possess racial Hit Dice. All shabti have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Constitution, +2 Charisma: Shabti have powerful bodies and presences to match."},{"type":"Native Outsider","value":"Shabti are outsiders with the native subtype."},{"type":"Medium","value":"Shabti are Medium creatures and receive no bonuses or penalties due to their size."},{"type":"Normal Speed","value":"Shabti have a base speed of 30 ft."},{"type":"Darkvision","value":"Shabti can see in the dark up to 60 ft.\n\nImmortal (1 RP), Immune to Undeath (1 RP), Past Life Knowledge (2 RP), Resist Level Drain (1 RP), Shattered Soul (-1 RP): See above."},{"type":"Spell-Like Ability (3 RP)","value":"Shabti can use suggestion once per day as a spell-like ability, with the caster level equal to the shabti's class level."},{"type":"Languages","value":"Shabti begin play speaking Common. Those with high Intelligence scores can choose any languages they want (except secret languages, such as Druidic)."}]}],"ecology":"Shabti are artificially created creatures, brought into being by mortal magic interfering with the natural course of souls. They are born when an individual of royal blood makes use of a rare magical item known as a sovereign shabti. The methods of creating these soul-guarding relics number among the deepest secrets of royal dynasties and cultic societies, meaning few mortals have access to such magic. However, groups on countless disparate worlds have discovered various routes to this power. This proliferation, along with the race's immortality, means that while shabti are rare sights in most planar metropolises, they are certainly not total strangers. They're practically unknown on the Material Plane, and are typically mistaken for aasimars or ifrits. Still, traditions and superstitions harkening back to this magic make the placement of mundane versions of these figurines-called ushabti-common in Osirian tombs\n\nShabti appear when a paranoid noble uses a sovereign shabti in an effort to avoid their judgment. They come into being full-grown and possessing glimpses from a life of privilege, yet knowing nothing of the magic that spawned them or the karmic debts they've been burdened with. Some appear on the terrifying thresholds of evil-aligned planes among legions of doomed petitioners. Others might simply wander onto the planes from the mists of the Maelstrom.\n\nMost shabti have golden skin that feels cool but not metallic, which is regularly accented by gemstone veins, nails, or other embellishments. Some have skin tones more similar to jade, ivory, or ebony. Apart from their distinctive colorations, shabti have anatomies similar to humans. However, all shabti are sterile, preventing the race from propagating naturally. As such, childlike shabti are exceedingly rare.","habitat_society":"Most shabti can be found in the planar metropolis of Axis, though Dis, Heaven's Shore, and the City of Brass also seem to be to many shabti's liking. Even in such places, though, shabti rarely gather in groups larger than two or three. Many seek to distinguish themselves from the magic items that spawned them, adopting self-chosen family names- \"Answerers\" and \"Crowns\" being popular among some.\n\nUpon their creation, shabti don't realize they're copies of another being. Each individual initially believes he is a deceased member of royalty, usually taking his rich appearance as a sign of divine favor or spiritual value. Most prove quite indignant, then distraught, in the face of their torture or forced labor. Eventually, they discover their unusual nature. Many deny the notion, choosing to live as if their copied memories were their own. Others face ages of depression, madness, and self-destruction. Some, however, embrace the freedom of a new, rare existence and seek to live up to the splendid forms fate has granted them.\n\nMany shabti learn of their nature from psychopomps. As Pharasma naturally despises such attempts to circumvent the natural cycle, her psychopomps are constantly on the lookout for shabti. When they find shabti, they immediately free them from any punishments, then use the shabti's memories to track down their mortal creators and bring them to justice.\n\nShabti Characters(13 RP)\n\nLiberated shabti often explore the planes, seeking to replace their false memories with unique experiences. Shabti are defined by their class levels-they don't possess racial Hit Dice. All shabti have the following racial traits.\n\n+2 Constitution, +2 Charisma: Shabti have powerful bodies and presences to match.\n\nNative Outsider: Shabti are outsiders with the native subtype.\n\nMedium: Shabti are Medium creatures and receive no bonuses or penalties due to their size.\n\nNormal Speed: Shabti have a base speed of 30 ft.\n\nDarkvision: Shabti can see in the dark up to 60 ft.\n\nImmortal (1 RP), Immune to Undeath (1 RP), Past Life Knowledge (2 RP), Resist Level Drain (1 RP), Shattered Soul (-1 RP): See above.\n\nSpell-Like Ability (3 RP): Shabti can use suggestion once per day as a spell-like ability, with the caster level equal to the shabti's class level.\n\nLanguages: Shabti begin play speaking Common. Those with high Intelligence scores can choose any languages they want (except secret languages, such as Druidic).","gear":"club, potion of cure moderate wounds"},{"name":"Skittergoat","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"animal","init":2,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 size","hp":9,"hd":"2d8","hdvalue":2,"fort":3,"ref":5,"will":0,"speed":[{"type":"land","speed":30}],"melee":"gore +3 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"egg cracker"}],"strength":12,"dexterity":14,"constitution":11,"intelligence":2,"wisdom":11,"charisma":5,"baseatk":1,"cmb":1,"cmd":13,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Escape Artist)"}],"skills":[{"skill":"Escape Artist","value":6,"special":"+8 to escape a grapple"},{"skill":"Perception","value":4}],"environments":["temperate hills","temperate plains"],"organizations":["solitary","pair","herd (3-12)"],"treasure":"none","description_visual":"This small goat has sharp horns that wrap around its head to point forward, making it resemble a tiny bull.","source":"AP 91","special_abilities":[{"type":"Egg Cracker","kind":"Ex","details":"A skittergoat's horns are able to crack through the tough shells of ankheg eggs. When a skittergoat charges, its gore attack is resolved against the target's touch AC. In addition, when breaking an object, a skittergoat ignores 1 point of the object's hardness."}],"description":"This breed of small goats, which dines almost exclusively on ankheg eggs, was only recently discovered living among the low hills and valleys of the Skittermounds. The skittergoats have adapted to life alongside the ankhegs with whom they share their environment: their agility allows them to slip through small spaces in search of eggs, and their speed makes them quite adept at escaping the grasp of angry ankheg mothers. Their relatively docile nature and ability to pierce ankheg eggs with their sharp horns have led to high demand for domesticated skittergoat companions among rangers searching for ankheg nests.\n\nSkittergoats don't often form large herds, since foraging for ankheg eggs is most effectively done alone. A mating pair of skittergoats will generally pair for life, with the female ranging out in search of food while the male stays near the den to protect the young. Mothers regurgitate food for their young after returning from a hunt.","ecology":"","habitat_society":""}];
